/** A layer of the room: where it sits (art pixels), its size, frames side by side and their speed. */
export interface ArtLayer {
  x: number;
  y: number;
  w: number;
  h: number;
  frames: number;
  fps: number;
}
export interface ArtTier extends ArtLayer {
  /** The generator whose count picks the level (a tier can have a second layer elsewhere). */
  of: string;
  /** Index = count level (0 = nothing shown). */
  levels: (ImageSourcePropType | null)[];
}
export interface ArtAmbient extends ArtLayer {
  id: string;
  src: ImageSourcePropType;
}
export interface ArtScene {
  room: ImageSourcePropType;
  /** Back to front. */
  order: string[];
  tiers: Record<string, ArtTier>;
  shelf: { x: number; y: number; w: number; h: number; levels: (ImageSourcePropType | null)[] } | null;
  ambient: ArtAmbient[];
  /** What the model stands on: drawn under it in the tap target, its feet `top` art pixels below the image's top edge. */
  plinth: { w: number; h: number; top: number; src: ImageSourcePropType } | null;
}

